"""Official screen capture cropped to the visible part of one exact owned Selection window."""
from pathlib import Path
import argparse,json,re,base64
from driver import ps,q
r=Path(__file__).resolve().parents[2];p=argparse.ArgumentParser();p.add_argument('--stage',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();s=json.loads(a.stage.read_text());assert s['owner']=='preflight'and s['component']=='selectionpage'and re.fullmatch(r'DBMV-Isolated-preflight-selectionpage-[0-9a-f]{32}',s['guestFolder']);assert json.loads((r/'docs/replica/ENVIRONMENT_LEASE.json').read_text())['resources']['windows']['owner']=='preflight'
code="$app=Join-Path (Join-Path $env:TEMP "+q(s['guestFolder'])+") 'app';Add-Type -AssemblyName System.Drawing;Add-Type 'using System;using System.Runtime.InteropServices;public static class SelectionCaptureGuard{[DllImport(\"user32.dll\")]public static extern IntPtr GetForegroundWindow();[DllImport(\"user32.dll\")]public static extern bool SetForegroundWindow(IntPtr h);[DllImport(\"user32.dll\")]public static extern int GetSystemMetrics(int n);}';$w=@([System.Windows.Automation.AutomationElement]::RootElement.FindAll([System.Windows.Automation.TreeScope]::Children,[System.Windows.Automation.Condition]::TrueCondition)|Where-Object{$_.Current.Name-eq 'Replica SelectionPage verification'-and(Get-Process -Id $_.Current.ProcessId).Path-eq($app+'\\ReplicaProbe.exe')});if($w.Count-ne 1){throw 'Unique cold Selection capture window required'};$w=$w[0];$handle=[IntPtr]::new($w.Current.NativeWindowHandle);[SelectionCaptureGuard]::SetForegroundWindow($handle)|Out-Null;Start-Sleep -Milliseconds 100;if([SelectionCaptureGuard]::GetForegroundWindow()-ne $handle){throw 'Owned Selection capture foreground mismatch'};$frame=$w.Current.BoundingRectangle;$screen=[System.Windows.Rect]::new([SelectionCaptureGuard]::GetSystemMetrics(76),[SelectionCaptureGuard]::GetSystemMetrics(77),[SelectionCaptureGuard]::GetSystemMetrics(78),[SelectionCaptureGuard]::GetSystemMetrics(79));$frame.Intersect($screen);if($frame.Width-lt500-or$frame.Height-lt400-or$frame.Width-gt4000-or$frame.Height-gt2400){throw 'Owned screen crop bounds invalid'};$bmp=[Drawing.Bitmap]::new([int]$frame.Width,[int]$frame.Height);$g=[Drawing.Graphics]::FromImage($bmp);$g.CopyFromScreen([int]$frame.Left,[int]$frame.Top,0,0,$bmp.Size);$ms=[IO.MemoryStream]::new();$bmp.Save($ms,[Drawing.Imaging.ImageFormat]::Png);[Console]::WriteLine([Convert]::ToBase64String($ms.ToArray()));$g.Dispose();$bmp.Dispose();$ms.Dispose();"
a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_bytes(base64.b64decode(ps(code)));print(a.output)
